function piggy_store_title($symbol)
{
    global $STORE_DATA;
    return isset($STORE_DATA[$symbol]) ? $STORE_DATA[$symbol]['title'] : $symbol;
}

function piggy_store_listings($symbol)
{
    global $STORE_DATA;
    return isset($STORE_DATA[$symbol]) ? $STORE_DATA[$symbol]['listings'] : array();
}